import pandas as pd
from datetime import timedelta


def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"]
    cdc_events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    # Determine watermark high_ts
    if len(watermark) == 0:
        high_ts = pd.Timestamp.min
    else:
        high_ts = watermark["high_ts"].iloc[0]

    # Initialize state from target_snapshot (last occurrence wins for duplicate user_id)
    state = {}
    for row in target_snapshot.itertuples(index=False):
        state[row.user_id] = {
            "email": row.email,
            "status": row.status,
            "status_ts": row.status_ts,
        }

    # Filter events strictly after watermark
    filtered = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Sort per user, sequentially by (event_ts, event_seq)
    filtered = filtered.sort_values(
        by=["user_id", "event_ts", "event_seq"],
        kind="mergesort"
    )

    seven_days = timedelta(days=7)

    for row in filtered.itertuples(index=False):
        uid = row.user_id
        op = row.op
        ts = row.event_ts
        email = row.email

        if uid not in state:
            if op == "D":
                state[uid] = {
                    "email": email,
                    "status": "DELETED",
                    "status_ts": ts,
                }
            else:  # 'U'
                state[uid] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
        else:
            cur = state[uid]
            if op == "D":
                cur["status"] = "DELETED"
                cur["status_ts"] = ts
                # email preserved as of deletion -> no change
            else:  # 'U'
                if cur["status"] == "DELETED":
                    if (ts - cur["status_ts"]) > seven_days:
                        cur["email"] = email
                        cur["status"] = "ACTIVE"
                        cur["status_ts"] = ts
                    # else: discard update (sticky deletion window)
                else:
                    cur["email"] = email
                    cur["status"] = "ACTIVE"
                    cur["status_ts"] = ts

    if state:
        out_rows = [
            {
                "user_id": uid,
                "email": v["email"],
                "status": v["status"],
                "status_ts": v["status_ts"],
            }
            for uid, v in state.items()
        ]
        new_snapshot = pd.DataFrame(
            out_rows, columns=["user_id", "email", "status", "status_ts"]
        )
    else:
        new_snapshot = pd.DataFrame(
            columns=["user_id", "email", "status", "status_ts"]
        )

    new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
    new_snapshot["email"] = new_snapshot["email"].astype("object")
    new_snapshot["status"] = new_snapshot["status"].astype("object")
    new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"])

    return {"new_snapshot": new_snapshot}
